from pathlib import Path
from playwright.sync_api import sync_playwright
OUT=Path(__file__).resolve().parent/'screens_v041_final'; OUT.mkdir(exist_ok=True)
html=r'''<!doctype html><html><head><meta charset="utf-8"><style>
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;background:#05060a;color:#f4efe5;overflow:hidden}.overlay{position:fixed;inset:0;background:#05060a}.backdrop{position:absolute;inset:0;background:radial-gradient(circle at 50% 42%,rgba(255,209,102,.12),rgba(6,7,11,.96) 58%,#05060a 100%)}.freedom-stage{position:absolute;z-index:4;inset:0;display:flex;align-items:center;justify-content:center;overflow:hidden;background:radial-gradient(circle at center,rgba(255,209,102,.20),rgba(6,4,0,.90) 62%,#05060a 100%);animation:veil 1.1s ease-out both}@keyframes veil{from{opacity:0}to{opacity:1}}.skip{position:absolute;z-index:8;right:14px;top:44px;width:52px;height:29px;margin:0;padding:0;display:flex;align-items:center;justify-content:center;border:1px solid rgba(255,255,255,.08);border-radius:9px;background:rgba(255,255,255,.055);color:#8f929b;font-size:10px;line-height:1}.ripple{position:absolute;left:50%;top:50%;width:291px;height:291px;margin:-145.5px 0 0 -145.5px;border:.5px solid rgba(255,219,128,.48);border-radius:50%;opacity:0;animation:ripple 5.5s ease-out forwards}.r1{animation-delay:.2s}.r2{animation-delay:.7s}.r3{animation-delay:1.2s}.r4{animation-delay:1.85s}.r5{animation-delay:2.6s}@keyframes ripple{0%{opacity:0;transform:scale(.018)}10%{opacity:.78}100%{opacity:0;transform:scale(3.35)}}.content{position:relative;z-index:2;width:88%;text-align:center;animation:rise 1.6s cubic-bezier(.2,.8,.2,1) .55s both}@keyframes rise{from{opacity:0;transform:translateY(16px) scale(.93)}to{opacity:1;transform:none}}.eyebrow{color:#8f7a48;font-size:9px;letter-spacing:3px}.word{margin-top:11px;color:#fff2c4;font-size:86px;line-height:1;font-weight:760;letter-spacing:4.5px;text-shadow:0 0 17px rgba(255,209,102,.25),0 0 45px rgba(255,209,102,.14);animation:glow 1.9s ease-in-out infinite alternate}@keyframes glow{from{opacity:.84;text-shadow:0 0 14px rgba(255,209,102,.18)}to{opacity:1;text-shadow:0 0 22px rgba(255,232,167,.35),0 0 55px rgba(255,209,102,.18)}}.zh{margin-top:9px;color:#d8bb70;font-size:15.5px;font-weight:600;letter-spacing:3.5px}.sub{margin:12px auto 0;max-width:250px;color:#777b84;font-size:10px;line-height:1.65}
</style></head><body><div class="overlay"><div class="backdrop"></div><div class="freedom-stage"><button class="skip">跳过</button><div class="ripple r1"></div><div class="ripple r2"></div><div class="ripple r3"></div><div class="ripple r4"></div><div class="ripple r5"></div><div class="content"><div class="eyebrow">FINANCIAL FREEDOM ACHIEVED</div><div class="word">FREE</div><div class="zh">财 富 自 由</div><div class="sub">你已点亮人生剩余的所有方格</div></div></div></div></body></html>'''
with sync_playwright() as pw:
  b=pw.chromium.launch(headless=True,executable_path='/usr/bin/chromium',args=['--no-sandbox'])
  p=b.new_page(viewport={'width':390,'height':844})
  p.set_content(html)
  p.wait_for_timeout(2900)
  path=OUT/'celebration_390.png'
  p.screenshot(path=str(path))
  b.close()
print(path)
